    function readProgramRows() {
        const firstRow = programBody.querySelector('tr');
        const globalUseOrder3 = Boolean(firstRow?.querySelector('[name="use_order_3"]')?.checked);
        const globalUseOrder4 = Boolean(firstRow?.querySelector('[name="use_order_4"]')?.checked);
        const existingItems = Array.isArray(state.form?.items) ? state.form.items : [];
        const existingConfigItem = existingItems.find((item) => item && item.programacao_config) || null;
        const programacaoConfig = existingConfigItem?.programacao_config || null;

        return [...programBody.querySelectorAll('tr')].map((row, index) => {
            const opInput = row.querySelector('[name="op"]');
            const op = opInput ? opInput.value : '';
            const parsed = {
                sequence: Number(row.querySelector('[name="sequence"]').value) || index + 1,
                op,
                sku: row.querySelector('[name="sku"]').value,
                quantity: Number(row.querySelector('[name="quantity"]').value) || 0,
                planned_start: index === 0 ? row.querySelector('[name="planned_start"]').value : '',
                use_order_3: globalUseOrder3,
                use_order_4: globalUseOrder4,
            };

            if (programacaoConfig) {
                parsed.programacao_config = programacaoConfig;
            }

            return parsed;
        });
    }
    function saveState(options = {}) {
        return persistDatasets(options);
    }

    async function persistDatasets({ notify = false, meta = {} } = {}) {
        if (!window.fetch) {
            return;
        }

        try {
            const response = await apiFetch('/controlepcp/api/datasets.php', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ datasets: { ...state.datasets, meta } }),
            });
            let payload = null;
            try {
                payload = await response.clone().json();
            } catch {
                payload = null;
            }

            if (!response.ok) {
                let message = payload?.message;
                if (!message) {
                    try {
                        message = (await response.text()).trim();
                    } catch {
                        message = '';
                    }
                }
                throw new Error(message || 'Falha ao salvar os dados.');
            }

            const data = payload ?? (await response.json());

            if (data && typeof data === 'object') {
                state.datasets = normalizeDatasets(data);
                // Re-renderizar navega??o da matriz ap?s persistir
                if (!state.datasets.setup_matrix[state.activeMatrixLine]) {
                    state.activeMatrixLine = '';
                }
                renderMatrix();
                if (notify && typeof showToast === 'function') {
                    showToast('Dados salvos no banco de dados.', 'success');
                }
            }
        } catch (error) {
            if (notify && typeof showToast === 'function') {
                showToast(error.message || 'Falha ao salvar os dados.', 'danger');
            }
        }
    }

    function formatNumber(value) {
        if (value === null || value === undefined || value === '') {
            return '';
        }

        return new Intl.NumberFormat('pt-BR').format(Number(value));
    }

    function flattenMatrix(matrix) {
        const rows = [];

        Object.entries(matrix || {}).forEach(([from, targets]) => {
            Object.entries(targets || {}).forEach(([to, duration]) => {
                rows.push({ from, to, duration });
            });
        });

        return rows.sort((left, right) => `${left.from}-${left.to}`.localeCompare(`${right.from}-${right.to}`));
    }

    function buildMatrix(rows) {
        const matrix = {};

        rows.forEach((row) => {
            const from = String(row.from || '').trim();
            const to = String(row.to || '').trim();
            const duration = String(row.duration || '').trim();

            if (!from || !to || !duration) {
                return;
            }

            if (!matrix[from]) {
                matrix[from] = {};
            }

            matrix[from][to] = duration;
        });

        return matrix;
    }

    function flattenMatrixSections(sections) {
        const rows = [];

        (sections || []).forEach((section) => {
            const line = String(section?.line || 'SEM LINHA').trim() || 'SEM LINHA';
            (section?.rows || []).forEach((row) => {
                rows.push({
                    line,
                    from: row.from,
                    to: row.to,
                    duration: row.duration,
                });
            });
        });

        return rows;
    }

    function normalizeMatrixSections(rawSections) {
        if (!Array.isArray(rawSections) || !rawSections.length) {
            return [];
        }

        if (rawSections.some((section) => Array.isArray(section?.rows))) {
            return rawSections
                .map((section) => ({
                    line: String(section?.line || 'SEM LINHA').trim() || 'SEM LINHA',
                    rows: Array.isArray(section?.rows)
                        ? section.rows
                            .map((row) => ({
                                from: String(row?.from || '').trim(),
                                to: String(row?.to || '').trim(),
                                duration: String(row?.duration || '').trim(),
                                line: String(row?.line || section?.line || 'SEM LINHA').trim() || 'SEM LINHA',
                            }))
                            .filter((row) => row.from && row.to && row.duration)
                        : [],
                }))
                .filter((section) => section.rows.length);
        }

        return buildMatrixSections(rawSections);
    }

    function buildMatrixSections(rows) {
        const sections = [];
        const byLine = new Map();

        (rows || []).forEach((row) => {
            const from = String(row.from || '').trim();
            const to = String(row.to || '').trim();
            const duration = String(row.duration || '').trim();
            const line = String(row.line || 'SEM LINHA').trim() || 'SEM LINHA';

            if (!from || !to || !duration) {
                return;
            }

            if (!byLine.has(line)) {
                const section = { line, rows: [] };
                byLine.set(line, section);
                sections.push(section);
            }

            byLine.get(line).rows.push({ from, to, duration, line });
        });

        return sections;
    }

    function getMatrixRowsWithLine() {
        const sectionRows = flattenMatrixSections(state.datasets.setup_matrix_sections || []);
        if (sectionRows.length) {
            return sectionRows;
        }

        return flattenMatrix(state.datasets.setup_matrix).map((row) => ({
            ...row,
            line: 'SEM LINHA',
        }));
    }

    function syncMatrixState(rows) {
        state.datasets.setup_matrix = buildMatrix(rows);
        state.datasets.setup_matrix_sections = buildMatrixSections(rows);
    }

    function renderMatrixImportSummary(sheets = state.matrixImportSheets) {
        if (!matrixImportSummary) {
            return;
        }

        const entries = Array.isArray(sheets) ? sheets : [];
        if (!entries.length) {
            matrixImportSummary.innerHTML = '<p class="matrix-import-summary-empty">Nenhuma planilha importada recentemente.</p>';
            return;
        }

        matrixImportSummary.innerHTML = `
            <div class="matrix-import-summary-heading">Planilhas importadas</div>
            <div class="matrix-import-summary-list">
                ${entries.map((sheet) => {
                    const name = escapeHtml(sheet.sheetName || 'Planilha');
                    const line = escapeHtml(sheet.lineLabel || 'SEM LINHA');
                    const count = Number.isFinite(sheet.count) ? sheet.count : 0;
                    const badge = count === 1 ? 'registro' : 'registros';
                    return `
                        <div class="matrix-import-summary-item">
                            <strong>${line}</strong>
                            <span class="matrix-import-summary-sheet">${name}</span>
                            <span class="matrix-import-summary-count">${count} ${badge}</span>
                        </div>`;
                }).join('')}
            </div>
        `;
    }
            
    function renderProgramacaoImportSummary(sheets = state.programacaoImportSheets) {
        if (!programacaoImportSheets) {
            return;
        }

        const entries = Array.isArray(sheets) ? sheets : [];
        if (!entries.length) {
            programacaoImportSheets.innerHTML = '<p class="muted">Nenhuma aba importada ainda.</p>';
            return;
        }

        const programadoCount = entries.filter((sheet) => sheet.status === 'programado').length;

        const calendarIntervals = Array.isArray(state.datasets?.calendar?.intervals) ? state.datasets.calendar.intervals : [];
        const weekDays = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sab'];

        const formatIntervalLabel = (order) => {
            const interval = calendarIntervals[order - 1] || null;
            const start = String(interval?.start || '').trim();
            const end = String(interval?.end || '').trim();
            if (!start || !end) {
                return '--:-- &agrave;s --:--';
            }
            return `${start} &agrave;s ${end}`;
        };

        const nextWorkdays = (() => {
            const result = [];
            const cursor = new Date();
            cursor.setHours(0, 0, 0, 0);

            while (result.length < 10) {
                const day = cursor.getDay();
                if (day !== 0) {
                    const yyyy = String(cursor.getFullYear());
                    const dd = String(cursor.getDate()).padStart(2, '0');
                    const mm = String(cursor.getMonth() + 1).padStart(2, '0');
                    const iso = `${yyyy}-${mm}-${dd}`;
                    const label = `${weekDays[day]} ${dd}/${mm}`;
                    result.push({ date: iso, label });
                }
                cursor.setDate(cursor.getDate() + 1);
            }

            return result;
        })();

        const ensureProgramacaoImportSheetUIState = (sheet) => {
            if (!sheet) {
                return { selected_day: '', efficiency: 100, orders_by_day: {} };
            }

            if (!sheet.programacao_ui) {
                sheet.programacao_ui = { selected_day: '', efficiency: 100, orders_by_day: {} };
            }

            const ui = sheet.programacao_ui;
            if (!ui.orders_by_day || typeof ui.orders_by_day !== 'object') {
                ui.orders_by_day = {};
            }

            const rawEfficiency = ui.efficiency ?? sheet.efficiency;
            const efficiencyValue = typeof rawEfficiency === 'string' && rawEfficiency.trim() === '' ? NaN : Number(rawEfficiency);
            ui.efficiency = Number.isFinite(efficiencyValue) ? efficiencyValue : 100;
            sheet.efficiency = ui.efficiency;

            nextWorkdays.forEach((workday) => {
                const date = workday.date;
                if (!ui.orders_by_day[date] || typeof ui.orders_by_day[date] !== 'object') {
                    ui.orders_by_day[date] = { 1: true, 2: true, 3: false, 4: false };
                    return;
                }

                if (typeof ui.orders_by_day[date][1] !== 'boolean') ui.orders_by_day[date][1] = true;
                if (typeof ui.orders_by_day[date][2] !== 'boolean') ui.orders_by_day[date][2] = true;
                if (typeof ui.orders_by_day[date][3] !== 'boolean') ui.orders_by_day[date][3] = false;
                if (typeof ui.orders_by_day[date][4] !== 'boolean') ui.orders_by_day[date][4] = false;
            });

            const defaultDay = nextWorkdays[0]?.date || '';
            if (!ui.selected_day || !ui.orders_by_day[ui.selected_day]) {
                ui.selected_day = defaultDay;
            }

            return ui;
        };

        const resolveSheetEfficiencyValue = (sheet) => {
            const ui = ensureProgramacaoImportSheetUIState(sheet);
            return ui.efficiency;
        };

        const buildWorkdaysPanelHtml = (sheet, index) => {
            const ui = ensureProgramacaoImportSheetUIState(sheet);
            const efficiencyValue = ui.efficiency;
            const selectedDay = String(ui.selected_day || '');

            const ordersByDayHtml = nextWorkdays.map((workday, dayIndex) => {
                const date = workday.date;
                const isSelected = selectedDay && selectedDay === date;
                const dayState = ui.orders_by_day?.[date] || { 1: true, 2: true, 3: false, 4: false };
                const cardStyle = isSelected
                    ? 'border:1px solid #2563eb;background:#eff6ff;'
                    : 'border:1px solid #e5e7eb;background:#fff;';

                const orderChecked = (order) => (dayState?.[order] ? 'checked' : '');

                return `
                    <div style="${cardStyle}border-radius:10px;padding:8px 10px;">
                        <button type="button" data-programacao-select-day="${escapeHtml(date)}" data-programacao-sheet-index="${String(index)}" style="display:block;width:100%;text-align:left;background:transparent;border:0;padding:0;margin:0;font-weight:700;font-size:12px;margin-bottom:6px;white-space:nowrap;cursor:pointer;">
                            ${workday.label}
                        </button>
                        <div style="display:flex;flex-direction:column;gap:4px;font-size:11px;line-height:1.2;">
                            <label style="display:flex;gap:6px;align-items:center;">
                                <input type="checkbox" ${orderChecked(1)} data-order="1" data-day="${dayIndex}" data-programacao-order="1" data-programacao-date="${escapeHtml(date)}" data-programacao-sheet-index="${String(index)}" style="width:14px;height:14px;margin:0;">
                                <span>ordem 1 &mdash; ${formatIntervalLabel(1)}</span>
                            </label>
                            <label style="display:flex;gap:6px;align-items:center;">
                                <input type="checkbox" ${orderChecked(2)} data-order="2" data-day="${dayIndex}" data-programacao-order="2" data-programacao-date="${escapeHtml(date)}" data-programacao-sheet-index="${String(index)}" style="width:14px;height:14px;margin:0;">
                                <span>ordem 2 &mdash; ${formatIntervalLabel(2)}</span>
                            </label>
                            <label style="display:flex;gap:6px;align-items:center;">
                                <input type="checkbox" ${orderChecked(3)} data-order="3" data-day="${dayIndex}" data-programacao-order="3" data-programacao-date="${escapeHtml(date)}" data-programacao-sheet-index="${String(index)}" style="width:14px;height:14px;margin:0;">
                                <span>ordem 3 &mdash; ${formatIntervalLabel(3)}</span>
                            </label>
                            <label style="display:flex;gap:6px;align-items:center;">
                                <input type="checkbox" ${orderChecked(4)} data-order="4" data-day="${dayIndex}" data-programacao-order="4" data-programacao-date="${escapeHtml(date)}" data-programacao-sheet-index="${String(index)}" style="width:14px;height:14px;margin:0;">
                                <span>ordem 4 &mdash; ${formatIntervalLabel(4)}</span>
                            </label>
                        </div>
                    </div>
                `;
            }).join('');

            return '<div style="flex:1;min-width:320px;max-width:740px;">' +
                '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">' +
                    '<label style="font-weight:700;font-size:12px;white-space:nowrap;">Efici&ecirc;ncia (%)</label>' +
                    '<input type="number" min="0" max="200" step="1" ' +
                        'data-programacao-efficiency="' + String(index) + '" ' +
                        'value="' + escapeHtml(String(efficiencyValue)) + '" ' +
                        'style="width:76px;padding:4px 6px;border:1px solid #e5e7eb;border-radius:10px;font-size:12px;line-height:1.1;">' +
                '</div>' +
                '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;">' +
                    ordersByDayHtml +
                '</div>' +
            '</div>';
        };

        const buttonsHtml = entries.map((sheet, index) => {
            const lineLabel = escapeHtml(sheet.lineLabel || sheet.lineCode || sheet.sheetName || 'Linha ' + String(index + 1));
            const status = sheet.status === 'programado' ? 'programado' : 'programar';
            const isProgramado = status === 'programado';
            const label = isProgramado ? 'Programado' : 'Programar';
            const disabledAttr = isProgramado ? 'disabled' : '';
            const buttonStyle = isProgramado ? 'background:#16a34a;color:#fff;border:none;' : '';
            const badgeStyle = isProgramado ? 'background:#16a34a;color:#fff;' : 'background:#e5e7eb;color:#111;';
            return '<div class="programacao-import-sheet-item" style="margin-bottom:12px;display:flex;gap:16px;align-items:flex-start;flex-wrap:wrap;">' +
                '<button type="button" class="programacao-import-sheet-button programacao-import-sheet-button--' + status + '" ' +
                'data-programacao-sheet="' + String(index) + '" ' +
                'data-programacao-status="' + status + '" ' +
                'style="border-radius:12px;padding:12px 16px;min-width:240px;display:flex;justify-content:space-between;align-items:center;gap:12px;' + buttonStyle + '" ' +
                disabledAttr + '>' +
                    '<span class="programacao-import-sheet-line" style="font-weight:700;white-space:nowrap;">' + lineLabel + '</span>' +
                    '<span class="programacao-import-sheet-status" style="border-radius:999px;padding:4px 10px;font-size:12px;' + badgeStyle + '">' +
                        label +
                    '</span>' +
                '</button>' +
                buildWorkdaysPanelHtml(sheet, index) +
            '</div>';
        }).join('');
        const summaryHeading = '<div class="programacao-import-summary-heading">Abas importadas</div>';
        const summaryMeta = '<div class="programacao-import-summary-meta">' +
            '<span>' + entries.length + ' ' + (entries.length === 1 ? 'aba importada' : 'abas importadas') + '</span>' +
            '<span>' + programadoCount + ' ' + (programadoCount === 1 ? 'programado' : 'programados') + '</span>' +
        '</div>';
        const sheetList = '<div class="programacao-import-sheet-list">' + buttonsHtml + '</div>';

        programacaoImportSheets.innerHTML = summaryHeading + summaryMeta + sheetList;

        programacaoImportSheets.querySelectorAll('[data-programacao-sheet]').forEach((button) => {
            button.addEventListener('click', (event) => {
                const status = button.dataset.programacaoStatus;
                if (button.disabled || status === 'programado') {
                    event.preventDefault();
                    showToast('OP já calculada', 'warning');
                    return;
                }
                const index = Number(button.dataset.programacaoSheet);
                 const sheet = Array.isArray(state.programacaoImportSheets)
                     ? state.programacaoImportSheets[index]
                     : null;
                 const ui = ensureProgramacaoImportSheetUIState(sheet);
                 const ordersByDay = ui.orders_by_day && typeof ui.orders_by_day === 'object' ? ui.orders_by_day : {};

                 const hasAnyMarkedOrder = (dayOrders) => {
                     if (!dayOrders || typeof dayOrders !== 'object') {
                         return false;
                     }
                     for (let order = 1; order <= 4; order++) {
                         if (Boolean(dayOrders[order] ?? dayOrders[String(order)])) {
                             return true;
                         }
                     }
                     return false;
                 };

                 const selectedDay = String(ui.selected_day || '');
                 const selectedDayOrders = ordersByDay?.[selectedDay] || null;
                 let effectiveSelectedDay = selectedDay;

                 if (!hasAnyMarkedOrder(selectedDayOrders)) {
                     effectiveSelectedDay = '';
                     for (const workday of nextWorkdays) {
                         const date = workday?.date ? String(workday.date) : '';
                         if (!date) {
                             continue;
                         }
                         const dayOrders = ordersByDay?.[date] || null;
                         if (hasAnyMarkedOrder(dayOrders)) {
                             effectiveSelectedDay = date;
                             break;
                         }
                     }

                     if (!effectiveSelectedDay) {
                         showToast('Nenhum dia com ordens marcadas nos prÃ³ximos 10 dias.', 'warning');
                         return;
                     }

                     ui.selected_day = effectiveSelectedDay;
                 }

                 const ordersForDay = ordersByDay?.[effectiveSelectedDay] || { 1: true, 2: true, 3: false, 4: false };
                 const programacaoConfig = {
                     selected_day: effectiveSelectedDay,
                     efficiency: ui.efficiency,
                     orders_by_day: ordersByDay,
                     orders: {
                         1: Boolean(ordersForDay[1]),
                         2: Boolean(ordersForDay[2]),
                         3: Boolean(ordersForDay[3]),
                         4: Boolean(ordersForDay[4]),
                     },
                 };
                 applyProgramacaoSheet(index);

                 if (Array.isArray(state.form.items) && state.form.items.length) {
                     const selectedDayStart = effectiveSelectedDay ? `${effectiveSelectedDay}T00:00` : '';
                     const useOrder3 = Boolean(programacaoConfig.orders?.[3]);
                     const useOrder4 = Boolean(programacaoConfig.orders?.[4]);

                    state.form.items = state.form.items.map((item, itemIndex) => {
                        if (!item || !item.sku) {
                            return item;
                        }
                        return {
                            ...item,
                            planned_start: itemIndex === 0 && selectedDayStart ? selectedDayStart : (item.planned_start || ''),
                            use_order_3: useOrder3,
                            use_order_4: useOrder4,
                            programacao_config: programacaoConfig,
                        };
                    });
                    renderProgram();
                }
            });
        });

        programacaoImportSheets.querySelectorAll('[data-programacao-efficiency]').forEach((input) => {
            input.addEventListener('input', () => {
                const index = Number(input.dataset.programacaoEfficiency);
                if (!Number.isFinite(index) || !Array.isArray(state.programacaoImportSheets) || !state.programacaoImportSheets[index]) {
                    return;
                }

                const value = input.value;
                const numericValue = value.trim() === '' ? NaN : Number(value);
                ensureProgramacaoImportSheetUIState(state.programacaoImportSheets[index]);
                state.programacaoImportSheets[index].efficiency = Number.isFinite(numericValue) ? numericValue : value;
                state.programacaoImportSheets[index].programacao_ui.efficiency = Number.isFinite(numericValue) ? numericValue : value;
            });
        });

        programacaoImportSheets.querySelectorAll('[data-programacao-order]').forEach((checkbox) => {
            checkbox.addEventListener('change', () => {
                const sheetIndex = Number(checkbox.dataset.programacaoSheetIndex);
                const date = String(checkbox.dataset.programacaoDate || '');
                const order = Number(checkbox.dataset.programacaoOrder);
                if (!Number.isFinite(sheetIndex) || !Array.isArray(state.programacaoImportSheets) || !state.programacaoImportSheets[sheetIndex]) {
                    return;
                }
                if (!date || !Number.isFinite(order) || order < 1 || order > 4) {
                    return;
                }

                const ui = ensureProgramacaoImportSheetUIState(state.programacaoImportSheets[sheetIndex]);
                if (!ui.orders_by_day[date]) {
                    ui.orders_by_day[date] = { 1: true, 2: true, 3: false, 4: false };
                }
                ui.orders_by_day[date][order] = Boolean(checkbox.checked);
            });
        });

        programacaoImportSheets.querySelectorAll('[data-programacao-select-day]').forEach((button) => {
            button.addEventListener('click', () => {
                const sheetIndex = Number(button.dataset.programacaoSheetIndex);
                const date = String(button.dataset.programacaoSelectDay || '');
                if (!Number.isFinite(sheetIndex) || !Array.isArray(state.programacaoImportSheets) || !state.programacaoImportSheets[sheetIndex]) {
                    return;
                }
                if (!date) {
                    return;
                }

                const ui = ensureProgramacaoImportSheetUIState(state.programacaoImportSheets[sheetIndex]);
                ui.selected_day = date;
                renderProgramacaoImportSummary();
            });
        });
    }
function applyProgramacaoSheet(index) {
        const sheet = Array.isArray(state.programacaoImportSheets)
            ? state.programacaoImportSheets[index]
            : null;
        if (!sheet) {
            return;
        }

        const rows = Array.isArray(sheet.rows) ? sheet.rows : [];
        if (!rows.length) {
            showToast('Nenhum item valido nesta aba.', 'danger');
            return;
        }

        const existingItems = Array.isArray(state.form.items) ? state.form.items : [];
        const parsedRows = rows.map((row, rowIndex) => {
            const rowScheduled = row.scheduledDate ? String(row.scheduledDate) : '';
            const plannedStart = rowScheduled
                ? (rowScheduled.includes('T') ? rowScheduled : rowScheduled + 'T00:00')
                : '';
            const referenceItem = existingItems[rowIndex] || {};
            return {
                op: String(row.op || referenceItem.op || '').trim(),
                sequence: Number(row.sequence) || 0,
                sku: String(row.sku || '').trim(),
                quantity: Number(row.quantity) || 0,
                planned_start: plannedStart,
            };
        }).filter((item) => item.sku);

        const sortedRows = parsedRows.sort((left, right) => (left.sequence || 0) - (right.sequence || 0));
        state.form.items = sortedRows.length ? sortedRows : [{}];
        state.activeProgramacaoSheetIndex = index;
        state.form.numero_op = '';
        if (numeroOpInput) {
            numeroOpInput.value = '';
        }
        renderProgram();
        enableCalculateMode();
        const label = sheet.lineLabel || sheet.lineCode || sheet.sheetName || `Linha ${index + 1}`;
        showToast(`${label} carregada.`);
    }

    function markProgramacaoAsProgramado() {
        if (!Array.isArray(state.programacaoImportSheets) || !state.programacaoImportSheets.length) {
            return;
        }

        const targetIndex = Number.isFinite(state.activeProgramacaoSheetIndex)
            ? state.activeProgramacaoSheetIndex
            : null;

        if (targetIndex === null || targetIndex < 0 || targetIndex >= state.programacaoImportSheets.length) {
            return;
        }

        state.programacaoImportSheets = state.programacaoImportSheets.map((sheet, index) => (
            index === targetIndex ? { ...sheet, status: 'programado' } : sheet
        ));
        renderProgramacaoImportSummary();
    }

    function defaultMatrixLineLabel() {
        const value = String(state.datasets.calendar.line || '').trim();
        if (!value) {
            return 'SEM LINHA';
        }

        const digits = value.replace(/\D+/g, '');
        return digits ? `LINHA ${digits}` : value.toUpperCase();
    }

    function getMatrixLines(rows = getMatrixRowsWithLine()) {
        return [...new Set(rows.map((row) => row.line || 'SEM LINHA'))]
            .sort((left, right) => left.localeCompare(right, 'pt-BR', { numeric: true }));
    }

    function getMatrixPageSize() {
        return 40;
    }
    function renderMatrixPagination(activeLine, totalRows) {
        if (!matrixPagination) {
            return;
        }

        const pageSize = getMatrixPageSize();
        const totalPages = Math.max(1, Math.ceil(totalRows / pageSize));
        const currentPage = Math.min(state.matrixPageByLine[activeLine] || 1, totalPages);
        state.matrixPageByLine[activeLine] = currentPage;

        if (totalRows <= pageSize) {
            matrixPagination.innerHTML = '';
            return;
        }

        matrixPagination.innerHTML = `
            <button type="button" class="matrix-page-button" data-page-action="prev" ${currentPage <= 1 ? 'disabled' : ''}>Anterior</button>
            <span class="matrix-page-label">Pagina ${currentPage} de ${totalPages} | ${totalRows} registros</span>
            <button type="button" class="matrix-page-button" data-page-action="next" ${currentPage >= totalPages ? 'disabled' : ''}>Proxima</button>
        `;

        matrixPagination.querySelectorAll('[data-page-action]').forEach((button) => {
            button.addEventListener('click', () => {
                const direction = button.dataset.pageAction;
                const nextPage = direction === 'prev' ? currentPage - 1 : currentPage + 1;
                state.matrixPageByLine[activeLine] = Math.min(totalPages, Math.max(1, nextPage));
                renderMatrix();
            });
        });
    }

    function renderMatrixLineNav(lines) {
        if (!matrixLineNav) {
            return;
        }

        if (!lines.length) {
            matrixLineNav.innerHTML = '';
            return;
        }

        if (!lines.includes(state.activeMatrixLine)) {
            state.activeMatrixLine = lines[0];
        }

        matrixLineNav.innerHTML = lines.map((line) => `
            <button type="button" class="matrix-line-tab ${line === state.activeMatrixLine ? 'is-current' : ''}" data-matrix-line="${line}">${line}</button>
        `).join('');

        matrixLineNav.querySelectorAll('[data-matrix-line]').forEach((button) => {
            button.addEventListener('click', () => {
                state.activeMatrixLine = button.dataset.matrixLine || '';
                renderMatrix();
            });
        });
    }

    function productOptions(selectedValue) {
        const entries = Object.entries(state.datasets.products || {});
        const options = ['<option value="">Selecione</option>'];
        const hasSelectedValue = entries.some(([sku]) => sku === selectedValue);
        const optionLabel = (sku, product) => {
            const description = String(product?.description || '').trim();
            return description ? sku + ' - ' + description : sku;
        };

        if (selectedValue && !hasSelectedValue) {
            options.push(`<option value="${selectedValue}" selected>${selectedValue}</option>`);
        }

        entries.forEach(([sku, product]) => {
            options.push(`<option value="${sku}" ${sku === selectedValue ? 'selected' : ''}>${optionLabel(sku, product)}</option>`);
        });

        return options.join('');
    }


    function normalizeCatalogValue(value) {
        return String(value || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toUpperCase()
            .replace(/\s+/g, ' ')
            .trim();
    }

    function buildProductLookup() {
        const lookup = new Map();

        Object.entries(state.datasets.products || {}).forEach(([sku, product]) => {
            const skuKey = normalizeCatalogValue(sku);
            const descriptionKey = normalizeCatalogValue(product?.description || '');

            if (skuKey) {
                lookup.set(skuKey, product);
            }

            if (descriptionKey) {
                lookup.set(descriptionKey, product);
            }
        });

        return lookup;
    }

    function getMatrixValidatedRows(rows = getMatrixRowsWithLine()) {
        const productLookup = buildProductLookup();

        return rows.reduce((list, row) => {
            const hasFrom = productLookup.has(normalizeCatalogValue(row.from));
            const hasTo = productLookup.has(normalizeCatalogValue(row.to));

            if (hasFrom && hasTo) {
                list.push({
                    line: row.line || 'SEM LINHA',
                    from: row.from || '-',
                    to: row.to || '-',
                    duration: row.duration || '-',
                });
            }

            return list;
        }, []);
    }

    function getMatrixInconsistencies(rows = getMatrixRowsWithLine()) {
        const productLookup = buildProductLookup();

        return rows.reduce((list, row) => {
            const issues = [];
            if (!productLookup.has(normalizeCatalogValue(row.from))) {
                issues.push('origem sem produto cadastrado');
            }
            if (!productLookup.has(normalizeCatalogValue(row.to))) {
                issues.push('destino sem produto cadastrado');
            }

            if (issues.length) {
                list.push({
                    line: row.line || 'SEM LINHA',
                    from: row.from || '-',
                    to: row.to || '-',
                    duration: row.duration || '-',
                    issues,
                });
            }

            return list;
        }, []);
    }

    function renderMatrixValidated(rows = getMatrixRowsWithLine()) {
        if (!matrixValidToggle || !matrixValidPanel || !matrixValidBody) {
            return;
        }

        const validatedRows = getMatrixValidatedRows(rows);
        matrixValidToggle.textContent = 'Registros validados (' + validatedRows.length + ')';
        matrixValidPanel.classList.toggle('is-hidden', !state.showMatrixValid);

        if (!state.showMatrixValid) {
            return;
        }

        if (!validatedRows.length) {
            matrixValidBody.innerHTML = '<div class="matrix-valid-empty">Nenhum registro validado entre matrizes e produtos.</div>';
            return;
        }

        matrixValidBody.innerHTML = validatedRows.map((item) => (
            '<div class="matrix-valid-card">'
                + '<strong>' + item.line + '</strong>'
                + '<span><b>Origem:</b> ' + item.from + '</span>'
                + '<span><b>Destino:</b> ' + item.to + '</span>'
                + '<span><b>Tempo:</b> ' + item.duration + '</span>'
            + '</div>'
        )).join('');
    }

    function renderMatrixIssues(rows = getMatrixRowsWithLine()) {
        if (!matrixIssuesToggle || !matrixIssuesPanel || !matrixIssuesBody) {
            return;
        }

        const inconsistencies = getMatrixInconsistencies(rows);
        matrixIssuesToggle.textContent = 'Inconsistencias (' + inconsistencies.length + ')';
        matrixIssuesPanel.classList.toggle('is-hidden', !state.showMatrixIssues);

        if (!state.showMatrixIssues) {
            return;
        }

        if (!inconsistencies.length) {
            matrixIssuesBody.innerHTML = '<div class="matrix-issues-empty">Nenhuma inconsistencia encontrada entre matrizes e produtos.</div>';
            return;
        }

        matrixIssuesBody.innerHTML = inconsistencies.map((row) => (
            '<div class="matrix-issue-card">'
                + '<span class="matrix-issue-line">' + escapeHtml(row.line || '') + '</span>'
                + '<div><strong>Origem:</strong> ' + escapeHtml(row.from || '') + '</div>'
                + '<div><strong>Destino:</strong> ' + escapeHtml(row.to || '') + '</div>'
                + '<div><strong>Tempo:</strong> ' + escapeHtml(row.duration || '') + '</div>'
                + '<div><strong>Motivo:</strong> ' + escapeHtml((row.issues || []).join(', ')) + '</div>'
            + '</div>'
        )).join('');
    }
    function setStatus(label, variant) {
        resultStatus.textContent = label;
        resultStatus.dataset.variant = variant;
    }

    function toggleResultPanel(visible) {
        resultPanel.classList.toggle('is-hidden', !visible);
    }

    function activateSection(sectionId) {
        const targetId = document.getElementById(sectionId) ? sectionId : DEFAULT_SECTION;
        state.activeSection = targetId;

        document.querySelectorAll('.app-section').forEach((section) => {
            section.classList.toggle('is-active', section.id === targetId);
        });

        document.querySelectorAll('.nav-shortcut, .home-card').forEach((button) => {
            button.classList.toggle('is-current', button.dataset.target === targetId);
        });
    }

    function intervalDaySelector(index, selectedDays) {
        return `
            <div class="weekday-inline-list">
                ${weekdays.map((day) => `
                    <label class="weekday-inline-item ${selectedDays.includes(day.value) ? 'is-selected' : ''}">
                        <input type="checkbox" data-calendar-index="${index}" data-day-value="${day.value}" ${selectedDays.includes(day.value) ? 'checked' : ''}>
                        <span>${day.label}</span>
                    </label>
                `).join('')}
            </div>
        `;
    }

    function normalizeHolidayList(values) {
        return values
            .map((value) => {
                if (typeof value === 'string') {
                    return { date: value.trim(), name: '' };
                }

                return {
                    date: String(value?.date || '').trim(),
                    name: String(value?.name || '').trim(),
                };
            })
            .filter((value) => value.date)
            .sort((left, right) => left.date.localeCompare(right.date))
            .filter((value, index, list) => index === list.findIndex((item) => item.date === value.date));
    }

    function syncHolidayState(values) {
        state.datasets.calendar.holidays = normalizeHolidayList(values);
        renderHolidayPreview();
        saveState();
    }

    function formatHolidayLabel(value) {
        const parts = String(value || '').split('-').map(Number);
        if (parts.length !== 3 || parts.some((part) => Number.isNaN(part))) {
            return value;
        }

        const [year, month, day] = parts;
        const date = new Date(year, month - 1, day);
        return new Intl.DateTimeFormat('pt-BR', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            weekday: 'long',
        }).format(date);
    }

    function renderHolidayPreview() {
        const holidays = state.datasets.calendar.holidays || [];

        if (!holidays.length) {
            holidayPreview.innerHTML = '<div class="holiday-empty">Nenhum feriado lancado.</div>';
            return;
        }

        holidayPreview.innerHTML = holidays.map((holiday) => `
            <div class="holiday-card">
                <div class="holiday-card-head">
                    <strong>${holiday.name || 'Feriado sem nome'}</strong>
                    <button type="button" class="holiday-remove" data-holiday-remove="${holiday.date}">Excluir</button>
                </div>
                <span>${formatHolidayLabel(holiday.date)}</span>
            </div>
        `).join('');

        holidayPreview.querySelectorAll('[data-holiday-remove]').forEach((button) => {
            button.addEventListener('click', () => {
                const holidayDate = button.dataset.holidayRemove;
                syncHolidayState((state.datasets.calendar.holidays || []).filter((item) => item.date !== holidayDate));
                showToast('Registro removido.');
            });
        });
    }
    function renderCalendar() {
        renderHolidayPreview();
        calendarBody.innerHTML = state.datasets.calendar.intervals.map((interval, index) => `
            <tr>
                <td>${index + 1}</td>
                <td>${intervalDaySelector(index, interval.days)}</td>
                <td><input type="time" data-calendar-index="${index}" data-field="start" value="${interval.start}" required></td>
                <td><input type="time" data-calendar-index="${index}" data-field="end" value="${interval.end}" required></td>
                <td class="actions-cell"><button type="button" class="row-delete" data-remove-interval="${index}">Remover</button></td>
            </tr>
        `).join('');

        calendarBody.querySelectorAll('[data-field]').forEach((input) => {
            input.addEventListener('change', () => {
                const index = Number(input.dataset.calendarIndex);
                const field = input.dataset.field;
                state.datasets.calendar.intervals[index][field] = input.value;
                saveState();
            });
        });

        calendarBody.querySelectorAll('[data-day-value]').forEach((input) => {
            input.addEventListener('change', () => {
                const index = Number(input.dataset.calendarIndex);
                const selected = [...calendarBody.querySelectorAll(`[data-calendar-index="${index}"][data-day-value]:checked`)]
                    .map((element) => Number(element.dataset.dayValue));

                state.datasets.calendar.intervals[index].days = selected.length ? selected : DEFAULT_INTERVAL_DAYS.slice();
                saveState();
            });
        });

        calendarBody.querySelectorAll('[data-remove-interval]').forEach((button) => {
            button.addEventListener('click', () => {
                state.datasets.calendar.intervals.splice(Number(button.dataset.removeInterval), 1);
                if (!state.datasets.calendar.intervals.length) {
                    state.datasets.calendar.intervals.push(normalizeInterval({}));
                }
                renderCalendar();
                saveState();
                showToast('Registro removido.');
            });
        });
    }

    function remapSkuReferences(fromSku, toSku) {
        state.form.items = state.form.items.map((item) => ({
            ...item,
            sku: item.sku === fromSku ? toSku : item.sku,
        }));
    }

    function removeMatrixReferences() {
        return;
    }

    function pruneCatalogReferences(availableSkus = Object.keys(state.datasets.products || {})) {
        const allowed = new Set(availableSkus);

        state.form.items = state.form.items.map((item) => ({
            ...item,
            sku: allowed.has(item.sku) ? item.sku : '',
        }));
    }

    function renderProducts() {
        const rows = Object.entries(state.datasets.products || {});
        productsBody.innerHTML = rows.map(([sku, product]) => `
            <tr>
                <td><input type="text" data-product-sku="${sku}" data-field="sku" value="${sku}" disabled></td>
                <td><input type="text" data-product-sku="${sku}" data-field="description" value="${product.description || ''}" disabled></td>
                <td><input type="text" data-product-sku="${sku}" data-field="reference_setup" value="${product.reference_setup || ''}" disabled></td>
                <td><input type="text" data-product-sku="${sku}" data-field="line" value="${product.line || 'L2'}" disabled></td>
                <td><input type="number" data-product-sku="${sku}" data-field="rate_per_hour" min="0" step="0.01" value="${product.rate_per_hour ?? ''}"></td>
                <td><input type="text" data-product-sku="${sku}" data-field="unit" value="${product.unit || 'cx'}" disabled></td>
                <td class="actions-cell"><button type="button" class="row-delete" data-update-product-rate="${sku}">Atualizar</button></td>
            </tr>
        `).join('');

        const productsCountLabel = document.getElementById('products-count');
        if (productsCountLabel) {
            productsCountLabel.textContent = String(rows.length);
        }

        productsBody.querySelectorAll('input').forEach((input) => {
            input.addEventListener('change', () => {
                const originalSku = input.dataset.productSku;
                const field = input.dataset.field;

                if (field === 'sku') {
                    const newSku = input.value.trim();
                    if (!newSku || newSku === originalSku) {
                        renderProducts();
                        return;
                    }

                    state.datasets.products[newSku] = { ...state.datasets.products[originalSku] };
                    delete state.datasets.products[originalSku];
                    remapSkuReferences(originalSku, newSku);
                    renderAllDatasetTables();
                    renderProgram();
                    saveState();
                    return;
                }

                const target = state.datasets.products[originalSku];
                if (!target) {
                    return;
                }

                if (field === 'rate_per_hour') {
                    target[field] = Number(input.value);
                    return;
                }

                target[field] = input.value;
                saveState();
            });
        });

        productsBody.querySelectorAll('[data-update-product-rate]').forEach((button) => {
            button.addEventListener('click', async () => {
                const sku = String(button.dataset.updateProductRate || '').trim();
                if (!sku) {
                    return;
                }

                const row = button.closest('tr');
                const rateInput = row?.querySelector('input[data-field="rate_per_hour"]');
                const rateRaw = String(rateInput?.value ?? '').trim();
                const rate = rateRaw === '' ? 0 : Number(rateRaw);

                try {
                    const response = await apiFetch('/controlepcp/api/datasets.php', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({
                            sku,
                            rate_per_hour: Number.isFinite(rate) ? rate : 0,
                        }),
                    });

                    const payload = await response.json().catch(() => null);
                    if (!response.ok) {
                        throw new Error(payload?.message || 'Falha ao atualizar producao/h.');
                    }

                    const product = state.datasets.products[sku];
                    if (product) {
                        product.rate_per_hour = Number.isFinite(rate) ? rate : 0;
                    }

                    showToast('Producao/h atualizada.', 'success');
                } catch (error) {
                    showToast(error.message || 'Falha ao atualizar producao/h.', 'danger');
                }
            });
        });
    }

    function matrixProductCell(sku) {
        const product = (state.datasets.products || {})[sku] || null;
        const description = product?.description || '';

        if (!sku && !description) {
            return '';
        }

        if (!description) {
            return `<span>${escapeHtml(sku || '')}</span>`;
        }

        return (
            `<div class="matrix-product-cell">` +
                `<div class="matrix-product-sku">${escapeHtml(sku || '')}</div>` +
                `<div class="matrix-product-description">${escapeHtml(description)}</div>` +
            `</div>`
        );
    }

    function renderMatrix() {
        const allRows = getMatrixRowsWithLine();
        const lines = getMatrixLines(allRows);
        renderMatrixLineNav(lines);

        if (!lines.length) {
            renderMatrixValidated([]);
            renderMatrixIssues([]);
            if (matrixPagination) {
                matrixPagination.innerHTML = '';
            }
            matrixBody.innerHTML = '<tr class="empty-state-row"><td colspan="4">Nenhuma matriz cadastrada ainda.</td></tr>';
            return;
        }

        const activeLine = state.activeMatrixLine || lines[0];
        const rows = allRows.filter((row) => row.line === activeLine);
        const pageSize = getMatrixPageSize();
        const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
        const currentPage = Math.min(state.matrixPageByLine[activeLine] || 1, totalPages);
        const pageStart = (currentPage - 1) * pageSize;
        const pagedRows = rows.slice(pageStart, pageStart + pageSize);
        state.matrixPageByLine[activeLine] = currentPage;

        renderMatrixValidated(allRows);
        renderMatrixIssues(allRows);
        renderMatrixPagination(activeLine, rows.length);

        matrixBody.innerHTML = pagedRows.map((row, index) => `
            <tr data-matrix-row="1" data-line="${row.line}" data-from="${escapeHtml(row.from || '')}" data-to="${escapeHtml(row.to || '')}">
                <td>${matrixProductCell(row.from || '')}</td>
                <td>${matrixProductCell(row.to || '')}</td>
                <td><input type="text" data-matrix-index="${pageStart + index}" data-field="duration" value="${row.duration || ''}"></td>
                <td class="actions-cell"><button type="button" class="row-delete" data-update-matrix-time="1">Atualizar</button></td>
            </tr>`
        ).join('');
        const readCurrentRows = () => {
            const preservedRows = allRows.filter((row) => row.line !== activeLine);
            const activeRows = rows.slice();
            const currentLineRows = [...matrixBody.querySelectorAll('tr[data-matrix-row="1"]')].map((row) => ({
                line: row.dataset.line || activeLine || 'SEM LINHA',
                from: row.dataset.from || '',
                to: row.dataset.to || '',
                duration: row.querySelector('[data-field="duration"]').value,
            }));

            currentLineRows.forEach((updatedRow, index) => {
                activeRows[pageStart + index] = updatedRow;
            });

            return {
                preservedRows,
                activeRows,
                mergedRows: [...preservedRows, ...activeRows],
            };
        };

        matrixBody.querySelectorAll('input').forEach((field) => {
            field.addEventListener('change', () => {
                const { mergedRows } = readCurrentRows();
                syncMatrixState(mergedRows);
                renderMatrixValidated(mergedRows);
                renderMatrixIssues(mergedRows);
            });
        });

        matrixBody.querySelectorAll('[data-update-matrix-time]').forEach((button) => {
            button.addEventListener('click', async () => {
                const row = button.closest('tr[data-matrix-row="1"]');
                const line = String(row?.dataset?.line || '').trim();
                const from = String(row?.dataset?.from || '').trim();
                const to = String(row?.dataset?.to || '').trim();
                const duration = String(row?.querySelector('input[data-field="duration"]')?.value || '').trim();

                if (!line || !from || !to) {
                    showToast('Linha/origem/destino invalidos.', 'danger');
                    return;
                }

                try {
                    const response = await apiFetch('/controlepcp/api/datasets.php', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            matrix: { line, from, to, duration },
                        }),
                    });

                    const payload = await response.json().catch(() => null);
                    if (!response.ok) {
                        throw new Error(payload?.message || 'Falha ao atualizar tempo.');
                    }

                    showToast('Tempo atualizado.', 'success');
                } catch (error) {
                    showToast(error.message || 'Falha ao atualizar tempo.', 'danger');
                }
            });
        });
        renderMatrixImportSummary();
    }
    function renderProgram() {
        programBody.innerHTML = '';
        const items = state.form.items.length ? state.form.items : [{}];
        const hasAnySku = items.some((item) => item && item.sku);
        const extraIntervals = Array.isArray(state.datasets.calendar?.intervals) ? state.datasets.calendar.intervals : [];

        const buildIntervalLabel = (order) => {
            const interval = extraIntervals[order - 1] || null;
            const start = String(interval?.start || '').trim();
            const end = String(interval?.end || '').trim();
            if (!start || !end) {
                return '--:-- &agrave;s --:--';
            }
            return `${start} &agrave;s ${end}`;
        };

        const activeSheetIndex = Number.isFinite(state.activeProgramacaoSheetIndex)
            ? state.activeProgramacaoSheetIndex
            : null;
        const activeSheet = activeSheetIndex !== null
            && Array.isArray(state.programacaoImportSheets)
            && activeSheetIndex >= 0
            && activeSheetIndex < state.programacaoImportSheets.length
            ? state.programacaoImportSheets[activeSheetIndex]
            : null;
        const activeUi = activeSheet?.programacao_ui || null;
        const activeSelectedDay = String(activeUi?.selected_day || '');
        const activeOrdersForDay = activeSelectedDay && activeUi?.orders_by_day?.[activeSelectedDay]
            ? activeUi.orders_by_day[activeSelectedDay]
            : null;

        const configFromItems = (items.find((item) => item && item.programacao_config) || null)?.programacao_config || null;
        const configFromActiveSheet = activeSelectedDay && activeOrdersForDay
            ? {
                selected_day: activeSelectedDay,
                efficiency: activeUi?.efficiency,
                orders: {
                    1: Boolean(activeOrdersForDay[1]),
                    2: Boolean(activeOrdersForDay[2]),
                    3: Boolean(activeOrdersForDay[3]),
                    4: Boolean(activeOrdersForDay[4]),
                },
            }
            : null;
        const resolvedProgramacaoConfig = configFromItems || configFromActiveSheet;
        const isNewFlowActive = Number.isFinite(state.activeProgramacaoSheetIndex) || Boolean(configFromItems);
        const shouldShowProgramConfigSummary = Boolean(hasAnySku && resolvedProgramacaoConfig?.selected_day);

        const formatIsoDatePt = (value) => {
            const match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
            if (!match) {
                return escapeHtml(value || '');
            }
            return `${match[3]}/${match[2]}/${match[1]}`;
        };

        if (entryTableWrap) {
            let summaryEl = entryTableWrap.querySelector('#program-config-summary');
            if (!summaryEl) {
                summaryEl = document.createElement('div');
                summaryEl.id = 'program-config-summary';
                summaryEl.style.cssText = 'display:none;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px;padding:8px 10px;border:1px solid #e5e7eb;border-radius:12px;background:#f8fafc;font-size:12px;line-height:1.2;';
                entryTableWrap.prepend(summaryEl);
            }

            if (!shouldShowProgramConfigSummary) {
                summaryEl.style.display = 'none';
                summaryEl.innerHTML = '';
            } else {
                const efficiencyValue = Number.isFinite(Number(resolvedProgramacaoConfig?.efficiency))
                    ? Number(resolvedProgramacaoConfig.efficiency)
                    : 100;
                const ordersActive = [1, 2, 3, 4].filter((order) => Boolean(resolvedProgramacaoConfig?.orders?.[order]));
                const ordersLabel = ordersActive.length ? ordersActive.join(', ') : '-';
                summaryEl.style.display = 'flex';
                summaryEl.innerHTML =
                    '<span style="font-weight:700;">Config.</span>' +
                    '<span>Data base: <strong>' + formatIsoDatePt(resolvedProgramacaoConfig.selected_day) + '</strong></span>' +
                    '<span>Efici&ecirc;ncia: <strong>' + escapeHtml(String(efficiencyValue)) + '%</strong></span>' +
                    '<span>Ordens: <strong>' + escapeHtml(String(ordersLabel)) + '</strong></span>';
            }
        }

        const legacyOrderOptionsStyle = isNewFlowActive
            ? 'display:none;'
            : 'display:flex;flex-direction:column;gap:2px;align-items:flex-start;margin-top:4px;';

        items.forEach((item, index) => {
            const row = document.createElement('tr');
            const extraOptions = index === 0
                ? `
                    <div style="${legacyOrderOptionsStyle}">
                        <label style="display:flex;gap:6px;align-items:center;font-size:11px;line-height:1.1;white-space:nowrap;opacity:0.92;">
                            <input type="checkbox" name="use_order_3" ${item.use_order_3 ? 'checked' : ''} style="width:14px;height:14px;min-height:0;padding:0;margin:0;cursor:pointer;">
                            ordem 3 &mdash; ${buildIntervalLabel(3)}
                        </label>
                        <label style="display:flex;gap:6px;align-items:center;font-size:11px;line-height:1.1;white-space:nowrap;opacity:0.92;">
                            <input type="checkbox" name="use_order_4" ${item.use_order_4 ? 'checked' : ''} style="width:14px;height:14px;min-height:0;padding:0;margin:0;cursor:pointer;">
                            ordem 4 &mdash; ${buildIntervalLabel(4)}
                        </label>
                    </div>
                `
                : '';

            row.innerHTML = `
                <td>
                    <input type="number" class="mini-input" name="sequence" value="${item.sequence || index + 1}" min="1" required>
                    ${extraOptions}
                </td>
                <td><input type="text" class="mini-input" name="op" value="${item.op || ""}"></td>
                <td><select name="sku" required>${productOptions(item.sku || '')}</select></td>
                <td><input type="number" name="quantity" min="1" step="1" value="${item.quantity || ''}" required></td>
                <td><input type="datetime-local" name="planned_start" value="${item.planned_start || ''}"></td>
                <td class="actions-cell"><button type="button" class="row-delete">Remover</button></td>
            `;
            programBody.appendChild(row);

            const plannedStart = row.querySelector('[name="planned_start"]');
            plannedStart.disabled = index !== 0;
            if (index !== 0) {
                plannedStart.value = '';
            }

            row.querySelector('.row-delete').addEventListener('click', () => {
                state.form.items.splice(index, 1);
                if (!state.form.items.length) {
                    state.form.items = [{}];
                }
                renderProgram();
                saveProgramDraftToStorage(state.form.items, state.datasets?.calendar?.line);
                saveState({ meta: { skip_products: true } });
            });

            row.querySelectorAll('input, select').forEach((field) => {
                field.addEventListener('change', syncProgramState);
                field.addEventListener('input', syncProgramState);
            });
        });
    }

    function syncProgramState() {
        state.form.items = readProgramRows();
        saveProgramDraftToStorage(state.form.items, state.datasets?.calendar?.line);
    }

    function renderSummary(result) {
        const productionRows = result.rows.filter((row) => row.type === 'production');
        const totalQty = productionRows.reduce((sum, row) => sum + (Number(row.quantity) || 0), 0);
        const calculatedRows = productionRows.filter((row) => row.status === 'Calculado').length;

        resultSummary.innerHTML = `
            <div class="summary-card"><span>Total de ordens</span><strong>${productionRows.length}</strong></div>
            <div class="summary-card"><span>Ordens calculadas</span><strong>${calculatedRows}</strong></div>
            <div class="summary-card"><span>Caixas programadas</span><strong>${formatNumber(totalQty)}</strong></div>
        `;
    }

    function parsePtBrDateTime(value) {
        if (!value || !value.includes(' ')) {
            return null;
        }

        const [datePart, timePart] = value.split(' ');
        const [day, month, year] = datePart.split('/').map(Number);
        const [hour, minute] = timePart.split(':').map(Number);
        return new Date(year, month - 1, day, hour || 0, minute || 0);
    }

    function formatEndMeta(row) {
        const endDate = parsePtBrDateTime(row.production_end);
        if (!endDate) {
            return '';
        }

        const dateLabel = new Intl.DateTimeFormat('pt-BR').format(endDate);
        const weekdayLabel = new Intl.DateTimeFormat('pt-BR', { weekday: 'long' }).format(endDate);

        return `<span class="end-meta">${dateLabel}<small>${weekdayLabel}</small></span>`;
    }

