    function renderRows(rows) {
        if (!rows.length) {
            resetResultArea(false);
            return;
        }

        renderRowsInto(rows, resultBody);
    }

    function disableCalculateMode() {
        if (calculateButton) {
            calculateButton.disabled = true;
        }
        if (numeroOpInput) {
            numeroOpInput.disabled = true;
        }
    }

    function enableCalculateMode() {
        if (calculateButton) {
            calculateButton.disabled = false;
        }
        if (numeroOpInput) {
            numeroOpInput.disabled = false;
        }
    }

    function renderResult(result, persist = true) {
        state.result = result;
        renderSummary(result);
        renderRows(Array.isArray(result?.rows) ? result.rows : []);

        const metaErrors = Array.isArray(result?.meta?.errors) ? result.meta.errors : [];
        const hasErrors = metaErrors.length > 0;
        setStatus(hasErrors ? 'Calculado com alertas' : 'Calculado', hasErrors ? 'warning' : 'success');

        toggleResultPanel(true);
        disableCalculateMode();

        if (persist) {
            saveState();
        }

        return !hasErrors;
    }
    function resetResultArea(persist = true) {
        state.result = null;
        resultSummary.innerHTML = '';
        resultBody.innerHTML = '<tr class="empty-state-row"><td colspan="10">Nenhuma simulacao calculada ainda.</td></tr>';
        setStatus('Aguardando calculo', 'idle');
        toggleResultPanel(false);
        enableCalculateMode();

        if (persist) {
            saveState();
        }
    }

    function renderAllDatasetTables() {
        renderCalendar();
        renderProducts();
        renderMatrix();
    }

    addIntervalButton.addEventListener('click', () => {
        state.datasets.calendar.intervals.push(normalizeInterval({}));
        renderCalendar();
        saveState();
        showToast('Registro salvo.');
    });

    importProductsButton.addEventListener('click', () => {
        productsImportFile?.click();
    });

    productsImportFile.addEventListener('change', async () => {
        const [file] = productsImportFile.files || [];
        if (!file) {
            return;
        }

        if (!file.name.toLowerCase().endsWith('.xlsx')) {
            showToast('Use um arquivo Excel no formato .xlsx.', 'danger');
            productsImportFile.value = '';
            return;
        }

        try {
            if (!window.PCPXlsxImport?.parseProducts) {
                throw new Error('Importacao de Excel indisponivel neste navegador.');
            }

            const imported = await window.PCPXlsxImport.parseProducts(file, state.datasets.calendar.line || 'L2');
            const importedProducts = imported.products || {};
            state.datasets.products = importedProducts;

            const lineCounts = {};
            Object.values(importedProducts).forEach((product) => {
                const line = String(product?.line || state.datasets.calendar.line || 'L2').trim();
                if (!line) {
                    return;
                }
                lineCounts[line] = (lineCounts[line] || 0) + 1;
            });

            const preferredLine = Object.keys(lineCounts)
                .sort((left, right) => (lineCounts[right] || 0) - (lineCounts[left] || 0))[0]
                || state.datasets.calendar.line
                || 'L2';
            state.datasets.calendar.line = preferredLine;

            pruneCatalogReferences(Object.keys(state.datasets.products));
            renderAllDatasetTables();
            renderProgram();
            await saveState({ meta: { preferred_line_code: preferredLine } });
            showToast(Number(imported.count || 0) + ' produtos importados.');
        } catch (error) {
            showToast(error.message || 'Falha ao importar o arquivo.', 'danger');
        } finally {
            productsImportFile.value = '';
        }
    });

    syncProductsButton?.addEventListener('click', async () => {
        try {
            const rows = [...productsBody.querySelectorAll('tr')];
            const products = {};

            rows.forEach((row) => {
                const sku = String(row.querySelector('input[data-field="sku"]')?.value || '').trim();
                if (!sku) {
                    return;
                }

                const description = String(row.querySelector('input[data-field="description"]')?.value || '').trim();
                const referenceSetup = String(row.querySelector('input[data-field="reference_setup"]')?.value || '').trim();
                const line = String(row.querySelector('input[data-field="line"]')?.value || '').trim();
                const rateRaw = String(row.querySelector('input[data-field="rate_per_hour"]')?.value ?? '').trim();
                const unit = String(row.querySelector('input[data-field="unit"]')?.value || '').trim();

                products[sku] = {
                    description,
                    reference_setup: referenceSetup,
                    line,
                    rate_per_hour: rateRaw === '' ? 0 : Number(rateRaw),
                    unit,
                };
            });

            const response = await apiFetch('/controlepcp/api/datasets.php', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    datasets: {
                        calendar: {
                            line: state.datasets.calendar.line || 'L2',
                        },
                        products,
                        meta: {
                            sync_products_only: true,
                        },
                    },
                }),
            });

            let payload = null;
            try {
                payload = await response.clone().json();
            } catch {
                payload = null;
            }

            if (!response.ok) {
                let message = payload?.message;
                if (!message) {
                    try {
                        message = (await response.text()).trim();
                    } catch {
                        message = '';
                    }
                }
                throw new Error(message || 'Falha ao salvar os dados.');
            }

            const data = payload ?? (await response.json());
            if (data && typeof data === 'object') {
                state.datasets = normalizeDatasets(data);
                if (!state.datasets.setup_matrix[state.activeMatrixLine]) {
                    state.activeMatrixLine = '';
                }
                renderAllDatasetTables();
                renderProgram();
                showToast('Produtos sincronizados no banco de dados.', 'success');
            }
        } catch (error) {
            showToast(error.message || 'Falha ao sincronizar produtos.', 'danger');
        }
    });

